import numpy as np
import pandas as pd
from datetime import datetime
import pytz

def r_as_POSIXct(x, tz="", *args, **kwargs):
    """
    Python reproduction of R's as.POSIXct.
    Handles origin offsets (R defaults to 1970-01-01 but accepts others)
    and timezone conversions.
    """
    # Extract origin if provided in kwargs (R's ... usually passes origin to as.POSIXct/as.POSIXlt)
    origin_str = kwargs.get('origin', '1970-01-01')

    # Handle the 'tz' default
    effective_tz = tz if tz != "" else "UTC"

    # Case 1: x is already POSIXct (represented as pandas Timestamp/DatetimeIndex)
    if isinstance(x, (pd.Timestamp, pd.DatetimeIndex)):
        if tz == "":
            return x
        if isinstance(x, pd.Timestamp):
            return x.tz_convert(effective_tz) if x.tzinfo else x.tz_localize('UTC').tz_convert(effective_tz)
        else:
            return x.tz_convert(effective_tz) if x.tz is not None else x.tz_localize('UTC').tz_convert(effective_tz)

    # Case 2: x is NULL (None)
    if x is None:
        return np.array([], dtype='datetime64[ns]')

    # Case 3: x is character or factor (strings)
    if isinstance(x, (str, list, np.ndarray)) and (isinstance(x, str) or (len(x) > 0 and isinstance(x[0], str))):
        try:
            ts = pd.to_datetime(x, errors='coerce')
            if isinstance(ts, pd.Timestamp):
                if ts.tzinfo is None:
                    ts = ts.tz_localize(effective_tz)
                else:
                    ts = ts.tz_convert(effective_tz)
                return ts
            else:
                if ts.tz is None:
                    ts = ts.tz_localize(effective_tz)
                else:
                    ts = ts.tz_convert(effective_tz)
                return ts.to_numpy()
        except Exception:
            return np.array([pd.NaT], dtype='datetime64[ns]')

    # Case 4: Numeric conversion (Crucial for 'origin' support)
    if isinstance(x, (int, float, np.ndarray, np.generic)) and np.issubdtype(getattr(x, 'dtype', type(x)), np.number):
        # Calculate the offset between R's origin and Unix Epoch (1970-01-01)
        # R's as.POSIXct for numeric treats x as seconds since origin.
        origin_dt = pd.to_datetime(origin_str).tz_localize('UTC')
        epoch_dt = pd.to_datetime('1970-01-01').tz_localize('UTC')
        offset_seconds = (origin_dt - epoch_dt).total_seconds()

        # Convert x to numpy array for consistent processing
        x_arr = np.atleast_1d(x).astype(float)

        # Result = (x + offset) seconds from 1970-01-01
        # Use pandas to handle the conversion to Timestamp
        timestamps = pd.to_datetime((x_arr + offset_seconds), unit='s', utc=True)

        # Apply timezone
        timestamps = timestamps.tz_convert(effective_tz)

        if np.isscalar(x) or (isinstance(x, (int, float))):
            return timestamps[0]
        return timestamps.to_numpy()

    # Case 5: x is logical and all NA
    if isinstance(x, np.ndarray) and x.dtype == bool:
        if np.all(pd.isna(x)):
            return np.array([pd.NaT] * len(x), dtype='datetime64[ns]')

    # If we reach here, R would throw a stop() error
    raise TypeError(f"do not know how to convert {type(x)} to class POSIXct")
